#include <bits/stdc++.h>

#define FOR(i, n) for (int i = 0; i < (n); ++i)
#define REVERSE(i, n) for (int i = (n) - 1; i >= 0; --i)

using namespace std;
using LL = long long;

struct CostFlow {
  struct Edge {
    int to;
    LL cap;
    LL cost;
    int rev_idx;
  };

  vector<vector<Edge>> adj;

  CostFlow(int n) : adj(n) {}

  void add_edge(int u, int v, LL capacity, LL weight) {
    int u_rev = adj[u].size();
    int v_rev = adj[v].size();
    adj[u].push_back({v, capacity, weight, v_rev});
    adj[v].push_back({u, 0, -weight, u_rev});
  }

  LL solve(int s, int t, LL flow) {
    LL total = 0;
    int n = adj.size();
    vector<LL> dist(n), potential(n);
    vector<int> parent(n), parent_edge(n);
    const LL INF = 1e18;
    while (flow > 0) {
      fill(dist.begin(), dist.end(), INF);
      dist[s] = 0;
      priority_queue<pair<LL, int>> pq;
      pq.emplace(0, s);
      while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        d = -d;
        if (dist[u] < d) continue;
        for (int i = 0; i < (int)adj[u].size(); ++i) {
          auto &e = adj[u][i];
          if (e.cap > 0 && dist[e.to] > dist[u] + e.cost + potential[u] - potential[e.to]) {
            dist[e.to] = dist[u] + e.cost + potential[u] - potential[e.to];
            parent[e.to] = u;
            parent_edge[e.to] = i;
            pq.emplace(-dist[e.to], e.to);
          }
        }
      }
      if (dist[t] == INF) return -1;
      for (int i = 0; i < n; ++i) potential[i] += dist[i];
      LL flow_now = flow;
      for (int v = t; v != s; v = parent[v]) {
        flow_now = min(flow_now, adj[parent[v]][parent_edge[v]].cap);
      }
      flow -= flow_now;
      total += flow_now * potential[t];
      for (int v = t; v != s; v = parent[v]) {
        auto &e = adj[parent[v]][parent_edge[v]];
        e.cap -= flow_now;
        adj[v][e.rev_idx].cap += flow_now;
      }
    }
    return total;
  }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  LL N, M, K, C, D;
  cin >> N >> M >> K >> C >> D;
  vector<int> A(K);
  FOR(i, K) cin >> A[i], A[i]--;
  vector<int> us(M), vs(M);
  FOR(i, M) {
    cin >> us[i] >> vs[i];
    us[i]--;
    vs[i]--;
  }
  CostFlow flow(N * 101 + 2);
  int s = N * 101;
  int t = s + 1;
  FOR(i, K) {
    flow.add_edge(s, A[i], 1, 0);
  }
  for (int i = 0; i <= 100; ++i) {
    flow.add_edge(N * i, t, K, C * i);
  }
  for (int i = 0; i < 100; ++i) {
    for (int j = 0; j < N; ++j) {
      flow.add_edge(i * N + j, (i + 1) * N + j, K, 0);
    }
    for (int j = 0; j < M; ++j) {
      for (int k = 1; k <= K; ++k) {
        flow.add_edge(N * i + us[j], N * (i + 1) + vs[j], 1, (2 * k - 1) * D);
        flow.add_edge(N * i + vs[j], N * (i + 1) + us[j], 1, (2 * k - 1) * D);
      }
    }
  }
  cout << flow.solve(s, t, K) << '\n';
}
